require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/ol_schema.php';require_once __DIR__.'/../includes/ol_pdf.php';require_login();require_premium();
if(!in_array(user_grade_number(),[10,11],true)){redirect('student/dashboard.php');}
$sid=filter_input(INPUT_GET,'subject_id',FILTER_VALIDATE_INT);$year=filter_input(INPUT_GET,'year',FILTER_VALIDATE_INT);$medium=medium_language((string)user()['medium']);
$paper=query_one('SELECT p.*,s.name_en,s.name_si,s.name_ta FROM ol_papers p JOIN subjects s ON s.id=p.subject_id WHERE p.subject_id=? AND p.year=? AND p.medium=? AND p.status=1','iis',[$sid,$year,$medium]);if(!$paper){flash('warning','This paper is not available.');redirect('ol-kuppiya/papers.php?subject_id='.$sid);}
ensure_ol_schema();$db=db();$st=$db->prepare('SELECT * FROM ol_paper_questions WHERE paper_id=? ORDER BY display_order,id');$st->bind_param('i',$paper['id']);$st->execute();$questions=$st->get_result()->fetch_all(MYSQLI_ASSOC);
if(!$questions){$pdf=realpath(__DIR__.'/../'.ltrim($paper['paper_file_path'],'/'));$text=$pdf?ol_pdf_text($pdf):'';$order=0;foreach($pdf?ol_read_questions($pdf):[] as $item){$ins=$db->prepare('INSERT IGNORE INTO ol_paper_questions(paper_id,question_number,question_text,display_order) VALUES(?,?,?,?)');$ins->bind_param('issi',$paper['id'],$item['number'],$item['text'],$order);$ins->execute();$order++;}$st=$db->prepare('SELECT * FROM ol_paper_questions WHERE paper_id=? ORDER BY display_order,id');$st->bind_param('i',$paper['id']);$st->execute();$questions=$st->get_result()->fetch_all(MYSQLI_ASSOC);}
$pageTitle='O/L paper';include __DIR__.'/../includes/header.php';?>
