<p><a href="papers.php?subject_id=<?=$sid?>">← Papers</a></p><section class="card ol-paper-hero"><span class="badge"><?=e(locale_value($paper,'name'))?> · <?=e(strtoupper($paper['medium']))?> medium</span><h1><?=intval($paper['year'])?> O/L paper</h1><p>Answer each question here. Official answers stay locked.</p><div class="ol-paper-actions"><a class="card" target="_blank" href="download.php?id=<?=$paper['id']?>&amp;type=paper"><span class="action-icon">📄</span><span><strong>View question paper</strong><small style="display:block;opacity:.72">Reference PDF</small></span></a><span class="card locked"><span class="action-icon">🔒</span><span><strong>Answer sheet locked</strong><small style="display:block;opacity:.72">Submit your answer first</small></span></span></div></section><section class="card" style="margin-top:16px"><div class="row" style="justify-content:space-between"><div><span class="badge">Exam workspace</span><h2><?=count($questions)?> extracted questions</h2></div><a class="btn good" href="<?=url('ol-kuppiya/discuss.php')?>?id=<?=$paper['id']?>">🤖 O/L AI Tutor</a></div></section>
<section><?php foreach($questions as $q):?><article class="card ol-question"><div class="row" style="justify-content:space-between"><span class="badge">Question <?=e($q['question_number'])?></span><a class="btn alt" href="<?=url('ol-kuppiya/discuss.php')?>?id=<?=$paper['id']?>&amp;q=<?=rawurlencode($q['question_number'])?>">Ask AI</a></div><p><?=e($q['question_text'])?></p><form method="post" action="submit_answer.php"><?=csrf_field()?><input type="hidden" name="question_id" value="<?=$q['id']?>"><textarea name="student_answer" required placeholder="Write your answer here..."></textarea><button class="good">Submit answer</button></form></article><?php endforeach;if(!$questions):?><article class="card muted">This PDF has no machine-readable text. Ask an administrator to enter the questions in the paper editor.</article><?php endif;?></section>
